<script setup>
import {inject as injectAdminConfirmation} from 'vue'
const {confirmAction}=injectAdminConfirmation('admin')
import {adminRoleLabel,adminDomainLabel} from '../../constants/adminPresentation'
import AdminFilterSummary from '../../components/admin/AdminFilterSummary.vue'
import AdminPageHeader from '../../components/admin/AdminPageHeader.vue'
import {useModalDraft} from '../../composables/useModalDraft'
import {ref,reactive,computed,inject,watch} from 'vue'
import {useAuthStore} from '../../stores/auth'
import {staffApi,rolesApi} from '../../api/adminOperations.api'
import {useServerList} from '../../composables/useServerList'
import {useApiState,useApiMutation} from '../../composables/useApiState'
import AdminModal from '../../components/admin/AdminModal.vue'
import DomainFields from '../../components/admin/DomainFields.vue'
import ApiFeedback from '../../components/admin/catalog/ApiFeedback.vue'
import ApiPagination from '../../components/admin/catalog/ApiPagination.vue'
const auth=useAuthStore(),{notify}=inject('admin'),list=useServerList(staffApi,{active:'',role:'',sort:'created_at',direction:'desc'}),roles=useApiState(),detail=useApiState(),mutation=useApiMutation(),open=ref(false),editing=ref(null),form=reactive({})
const filterDefaults={...list.filters}
const roleOptions=computed(()=> (roles.data.value||['super_admin','manager','cashier','kitchen'].map(name=>({name,permissions:null}))).filter(r=>!['customer','driver'].includes(r.name)&&(auth.hasRole('super_admin')||r.name!=='super_admin'&&(!r.permissions||r.permissions.every(p=>auth.can(p))))).map(r=>({value:r.name,label:adminRoleLabel(r.name)})))
const fields=computed(()=>[{key:'name',label:'الاسم',required:true,max:150},{key:'phone',label:'رقم الجوال',required:true,max:16,pattern:'\\+[1-9][0-9]{7,14}',dir:'ltr',help:'مثال: 0551234567'},{key:'email',label:'البريد الإلكتروني (اختياري)',type:'email',max:255},{key:'password',label:editing.value?'كلمة مرور جديدة (اتركها فارغة للإبقاء على الحالية)':'كلمة المرور',type:'password',required:!editing.value,minlength:12,max:72,help:'12 حرفًا على الأقل، بحروف كبيرة وصغيرة وأرقام.'},{key:'roles',label:'الأدوار',type:'multi',options:roleOptions.value}])
function allowedTarget(row){return auth.hasRole('super_admin')||!row.roles.includes('super_admin')&&row.permissions.every(p=>auth.can(p))}
async function edit(row){if(detail.loading.value||mutation.busy.value)return;mutation.error.value=null;editing.value=row;let value=row;if(row)value=await detail.run(()=>staffApi.show(row.id));if(row&&!value)return;if(row)editing.value=value;Object.assign(form,{name:value?.name||'',phone:value?.phone||'',email:value?.email||'',password:'',roles:[...(value?.roles||[])]});open.value=true}
async function save(){const payload={name:form.name,phone:form.phone,email:form.email||null};const rolesChanged=!editing.value||JSON.stringify([...form.roles].sort())!==JSON.stringify([...(editing.value.roles||[])].sort());if(rolesChanged)payload.roles=form.roles;if(form.password)payload.password=form.password;if(editing.value&&(rolesChanged||form.password)&&!(await confirmAction('تغيير الأدوار أو كلمة المرور ينهي جلسات الموظف الحالية. متابعة؟')))return;const result=await mutation.run(()=>editing.value?staffApi.update(editing.value.id,payload):staffApi.create(payload));if(result.ok){open.value=false;form.password='';notify('تم حفظ الموظف على الخادم.');await list.load();if(editing.value?.id===auth.adminProfile?.id)await auth.fetchMe().catch(()=>{})}}
async function activate(row){if(!(await confirmAction((row.is_active?'إيقاف':'تفعيل')+' الموظف '+row.name+'؟')))return;const result=await mutation.run(()=>row.is_active?staffApi.deactivate(row.id):staffApi.activate(row.id));if(result.ok){notify('تم تحديث حالة الموظف.');list.load()}}
list.load();if(auth.can('roles.view'))roles.run(signal=>rolesApi.list(signal))
watch(open,value=>{if(!value)form.password=''})
const beforeClose=useModalDraft(open,form,mutation.busy)
</script>
<template><main id="main"><AdminPageHeader class="page-heading"><div><span class="eyebrow">إدارة شيشلي</span><h1>الموظفون</h1><p class="muted">الحسابات والأدوار وحالة الوصول</p></div><button v-if="auth.can('staff.create')" class="button" :disabled="mutation.busy.value||detail.loading.value||roles.loading.value" @click="edit(null)">إضافة موظف</button></AdminPageHeader><section class="panel"><form class="toolbar" @submit.prevent="list.search"><input v-model="list.filters.search" type="search" aria-label="بحث الموظفين" maxlength="150" placeholder="الاسم أو الهاتف أو البريد"><select v-model="list.filters.active" aria-label="حالة الموظف"><option value="">كل الحالات</option><option value="1">نشط</option><option value="0">متوقف</option></select><select v-model="list.filters.role" aria-label="الدور"><option value="">كل الأدوار</option><option v-for="role in roleOptions" :key="role.value" :value="role.value">{{ role.label }}</option></select><button class="button" :disabled="list.state.loading.value">بحث</button></form><AdminFilterSummary :filters="list.filters" :defaults="filterDefaults" :busy="list.state.loading.value" @clear="Object.assign(list.filters,filterDefaults);list.search()"/><ApiFeedback :loading="list.state.loading.value" :error="list.state.error.value" @retry="list.load"/><ApiFeedback variant="inline" :loading="detail.loading.value||roles.loading.value" :error="detail.error.value||roles.error.value" @retry="auth.can('roles.view')&&roles.run(signal=>rolesApi.list(signal))"/><div v-if="list.state.data.value" class="table-wrap"><table v-admin-table><thead><tr><th>الموظف</th><th>التواصل</th><th>الأدوار</th><th>الحالة</th><th>الإجراءات</th></tr></thead><tbody><tr v-for="row in list.state.data.value.data" :key="row.id"><td><div class="admin-cell-value">{{ row.name }}</div></td><td><div class="admin-cell-value"><bdi>{{ row.phone }}</bdi><br>{{ row.email }}</div></td><td><div class="admin-cell-value">{{ row.roles.map(adminRoleLabel).join('، ') }}</div></td><td><div class="admin-cell-value"><span class="badge" :class="row.is_active?'good':'off'">{{ row.is_active?'نشط':'متوقف' }}</span></div></td><td><div class="admin-cell-value"><div class="admin-row-actions"><button v-if="auth.can('staff.update')&&allowedTarget(row)" class="row-button" :disabled="mutation.busy.value||detail.loading.value" @click="edit(row)">تعديل</button><button v-if="auth.can(row.is_active?'staff.deactivate':'staff.activate')&&allowedTarget(row)&&(!row.is_active||row.id!==auth.adminProfile?.id)" class="row-button" :class="{danger:row.is_active}" :disabled="mutation.busy.value" @click="activate(row)">{{ row.is_active?'إيقاف':'تفعيل' }}</button></div></div></td></tr></tbody></table><p v-if="!list.state.data.value.data.length" class="empty">لا يوجد موظفون مطابقون.</p></div><ApiPagination :meta="list.state.data.value?.meta" :links="list.state.data.value?.links" :busy="list.state.loading.value" @page="list.changePage"/><ApiFeedback :error="mutation.error.value" @retry="mutation.error.value=null"/></section><AdminModal :before-close="beforeClose" v-model:open="open" :title="editing?'تعديل الموظف':'إضافة موظف'" :busy="mutation.busy.value" @submit="save"><p v-if="!auth.can('roles.view')" class="form-note">لا تتوفر تفاصيل صلاحيات الأدوار لهذا الحساب؛ يتحقق الخادم من أهلية التكليف عند الحفظ.</p><DomainFields :fields="fields" :form="form" :errors="mutation.error.value?.errors" :disabled="mutation.busy.value"/><ApiFeedback :error="mutation.error.value" @retry="mutation.error.value=null"/><div class="form-actions"><button class="button" :disabled="mutation.busy.value||(!editing&&!roleOptions.length)">حفظ الموظف</button></div></AdminModal></main></template>
